function renderResults() { const list=data.entities.filter(matches).sort((a,b)=>a.kind.localeCompare(b.kind,'zh-CN')||a.name.localeCompare(b.name,'zh-CN'));resultCount.textContent=search.value.trim()?`${list.length} 个匹配实体`:`${list.length} 个可观测实体`;resultHint.textContent=active==='all'?'按类别筛选或检索':groupLabel(active);results.innerHTML=list.length?list.map(entity=>`<button type="button" class="result-item${entity.id===selectedId?' is-active':''}" data-result="${esc(entity.id)}" role="listitem"><i style="background:${data.palette[entity.group]||data.palette.belt}"></i><span><b>${esc(entity.name)}</b><small>${esc(typeLabels[entity.kind]||entity.kind)} · ${esc(entity.role||groupLabel(entity.group))}</small></span></button>`).join(''):'<p class="empty-results">没有匹配实体。可清除检索词或切换观测层。</p>';results.querySelectorAll('[data-result]').forEach(button=>button.addEventListener('click',()=>selectEntity(button.dataset.result,true))); }
const cosmos=new Cosmos(document.getElementById('cosmos'),data,body=>selectEntity(body.id,true));let viewSaveTimer=null;cosmos.onViewChange=view=>{viewStates[spaceKey()]=view;updateTargetTelemetry();if(viewSaveTimer)return;viewSaveTimer=setTimeout(()=>{viewSaveTimer=null;saveNavigationState();},400);};addEventListener('pagehide',()=>{if(viewSaveTimer){clearTimeout(viewSaveTimer);viewSaveTimer=null;saveNavigationState();}});
function localLayout(ids,kind='field'){const positions={};if(kind==='belt'){const groups=[ids.filter(id=>['text','organization'].includes(entityById(id)?.kind)),ids.filter(id=>entityById(id)?.group==='event'||['industrialization','five-year-plans'].includes(id)),ids.filter(id=>entityById(id)?.group==='war'),ids.filter(id=>entityById(id)?.group==='legacy'),ids.filter(id=>!['text','organization'].includes(entityById(id)?.kind)&&!['event','war','legacy'].includes(entityById(id)?.group))];groups.forEach((items,row)=>items.forEach((id,index)=>{const angle=((index+1)/(items.length+1)*Math.PI*1.5)-Math.PI*.75,radius=155+row*72;positions[id]={x:Math.cos(angle)*radius,y:(row-2)*42,z:Math.sin(angle)*radius};}));return positions;}const center=ids.includes('stalin')?'stalin':ids[0];positions[center]={x:0,y:0,z:0};ids.filter(id=>id!==center).forEach((id,index,items)=>{const ring=index<5?190:index<10?320:430,slot=index<5?index:index<10?index-5:index-10,total=index<5?5:index<10?5:Math.max(1,items.length-10),angle=(slot/total*Math.PI*2)-Math.PI/2;positions[id]={x:Math.cos(angle)*ring,y:Math.sin(angle*2)*34,z:Math.sin(angle)*ring};});return positions;}
